// Scene-relative anchors; DP metrics arrive as physical pixels. Stroke alignment retains texel units.
return {
  resolutionPosition: [width * 0.5, height * 0.925] as vec2,
  resolutionSize: [width * 0.5555555555555556 - horizontalPadding2Px, resolutionHeightPx] as vec2,
  teamPosition: [width * 0.5, height * 0.875 + teamOffsetPx] as vec2,
  teamSize: [width * 0.3333333333333333 - horizontalPadding2Px, teamHeightPx] as vec2,
  titlePosition: [width * 0.5, height * 0.875 + titleOffsetPx] as vec2,
  titleSize: [width * 0.3333333333333333 - horizontalPadding2Px, titleHeightPx] as vec2,
};

// Scene-relative anchors; DP metrics arrive as physical pixels. Stroke alignment retains texel units.
return {
  emailPosition: [width * 0.5, height * 0.025 + emailOffsetPx] as vec2,
  emailSize: [width * 0.3333333333333333 - horizontalPadding2Px, emailHeightPx] as vec2,
  datePosition: [width * 0.5, height * 0.025 + dateOffsetPx] as vec2,
  dateSize: [width * 0.3333333333333333 - horizontalPadding2Px, dateHeightPx] as vec2,
};
